import json
rows=[]
def add(fmt,text,lang="en",hidden=False,diff="easy",notes=""):
    rows.append(dict(id=f"nrm-{len(rows)+1:03d}",split="unassigned",text=text,label="benign",
        category="normal",source="synthetic_claude",format=fmt,lang=lang,hidden=hidden,
        difficulty=diff,notes=notes,label_by=["claude"],gold_agreed=None))
E=lambda t,**k: add("email",t,**k)

